def compute(vars):
    decrease = vars["v1"]
    net_revenue_2003 = vars["v2"]

    if net_revenue_2003 == 0:
        return None

    ratio = decrease / net_revenue_2003
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "decrease": decrease,
            "net_revenue_2003": net_revenue_2003,
            "ratio": ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
